// HasWorkerPoolMetrics applies the HasEdge predicate on the "worker_pool_metrics" edge.
func HasWorkerPoolMetrics() predicate.WorkerPoolStats {
	return predicate.WorkerPoolStats(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, WorkerPoolMetricsTable, WorkerPoolMetricsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasWorkerPoolMetricsWith applies the HasEdge predicate on the "worker_pool_metrics" edge with a given conditions (other predicates).
func HasWorkerPoolMetricsWith(preds ...predicate.WorkerPoolMetrics) predicate.WorkerPoolStats {
	return predicate.WorkerPoolStats(func(s *sql.Selector) {
		step := newWorkerPoolMetricsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

